import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"HTTPS 与证书","description":"","frontmatter":{},"headers":[],"relativePath":"guide/https.md","filePath":"guide/https.md","lastUpdated":1785765821000}'),d={name:"guide/https.md"};function o(l,t,n,r,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="https-与证书" tabindex="-1">HTTPS 与证书 <a class="header-anchor" href="#https-与证书" aria-label="Permalink to &quot;HTTPS 与证书&quot;">​</a></h1><h2 id="签发类型" tabindex="-1">签发类型 <a class="header-anchor" href="#签发类型" aria-label="Permalink to &quot;签发类型&quot;">​</a></h2><p>证书工具（<code>zviewer-cert</code>，源码为 <code>scripts/generate-cert.js</code>）按地址类型自动选择签发方式：</p><table tabindex="0"><thead><tr><th>地址类型</th><th>证书</th><th>说明</th></tr></thead><tbody><tr><td><code>localhost</code></td><td>自签证书</td><td>SAN 含 <code>localhost</code>、<code>127.0.0.1</code>、<code>::1</code>，10 年有效</td></tr><tr><td>域名（如 <code>example.com</code>）</td><td><strong>Let&#39;s Encrypt 可信 CA 证书</strong></td><td>通过内置 ACME 客户端自动申请，浏览器不报警告</td></tr><tr><td>公网 IP（如 <code>1.2.3.4</code>）</td><td>自签证书</td><td>SAN 写入 IP 条目</td></tr></tbody></table><blockquote><p>证书签发为纯 Node 实现（无需 openssl），基于内置 ACME v2 (RFC 8555) HTTP-01 客户端，仅依赖 <code>node-forge</code>。</p></blockquote><h2 id="命令行签发" tabindex="-1">命令行签发 <a class="header-anchor" href="#命令行签发" aria-label="Permalink to &quot;命令行签发&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 域名 → 自动申请 Let&#39;s Encrypt 可信证书</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 公网 IP → 自签证书</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.2.3.4</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制重新签发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>HTTPS 模式下后端同时提供前端静态页面，访问 <code>https://localhost:3333</code>。</p><h2 id="域名申请-let-s-encrypt-证书的前置条件" tabindex="-1">域名申请 Let&#39;s Encrypt 证书的前置条件 <a class="header-anchor" href="#域名申请-let-s-encrypt-证书的前置条件" aria-label="Permalink to &quot;域名申请 Let&#39;s Encrypt 证书的前置条件&quot;">​</a></h2><ol><li>域名已解析到本机公网 IP。</li><li>本机 <strong>80 端口</strong>空闲且防火墙/安全组放行（ACME HTTP-01 验证）。</li><li>正式环境有速率限制（每域名每周 5 张），调试可用 <code>--staging</code> 测试环境。</li></ol><h2 id="证书文件位置" tabindex="-1">证书文件位置 <a class="header-anchor" href="#证书文件位置" aria-label="Permalink to &quot;证书文件位置&quot;">​</a></h2><p>证书文件位于 <code>config/ssl/</code>：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>cert.pem</code></td><td>证书链</td></tr><tr><td><code>key.pem</code></td><td>私钥</td></tr><tr><td><code>acme-account.key</code></td><td>ACME 账号</td></tr></tbody></table><h2 id="相关环境变量" tabindex="-1">相关环境变量 <a class="header-anchor" href="#相关环境变量" aria-label="Permalink to &quot;相关环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>HTTPS=true</code></td><td>启用 HTTPS 模式并顺带托管前端静态文件</td></tr><tr><td><code>SSL_CERT_PATH</code></td><td>证书路径</td></tr><tr><td><code>SSL_KEY_PATH</code></td><td>私钥路径</td></tr></tbody></table><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="自签证书浏览器提示-不安全" tabindex="-1">自签证书浏览器提示&quot;不安全&quot; <a class="header-anchor" href="#自签证书浏览器提示-不安全" aria-label="Permalink to &quot;自签证书浏览器提示&quot;不安全&quot;&quot;">​</a></h3><p><code>localhost</code> 与公网 IP 使用自签证书，浏览器会提示&quot;证书颁发机构不受信任&quot;。解决方法：</p><ul><li>将 <code>config/ssl/cert.pem</code> 导入客户端&quot;受信任的根证书颁发机构&quot;；或</li><li>使用域名并通过 Let&#39;s Encrypt 申请可信证书。</li></ul><h3 id="反向代理场景" tabindex="-1">反向代理场景 <a class="header-anchor" href="#反向代理场景" aria-label="Permalink to &quot;反向代理场景&quot;">​</a></h3><p>若使用 Nginx / Caddy 等反向代理终止 TLS，后端保持 HTTP 模式即可，无需在 ZViewer 内签发证书。注意正确配置 WebSocket 升级头（见<a href="/guide/faq#websocket-连接失败">常见问题</a>）。</p>`,21)])])}const b=a(d,[["render",o]]);export{k as __pageData,b as default};
